import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, uv, vec3, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  const group = new Group();
  group.name = 'home-headline';

  // ---- Resolve spec colors ----
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {};
  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const accent = new Color(colors.accent ?? '#ff2a38');
  const surface = new Color(colors.surface ?? '#0b0b10');

  const inkNode = vec3(ink.r, ink.g, ink.b);
  const surfNode = vec3(surface.r, surface.g, surface.b);
  const accentNode = vec3(accent.r, accent.g, accent.b);
  const paperNode = vec3(paper.r, paper.g, paper.b);

  // ---- Backdrop gradient plane (engineered surface) ----
  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    new MeshBasicNodeMaterial({ toneMapped: false })
  );
  backdrop.position.set(0, 0, -2.5);
  // Vertical gradient: surface (bottom) -> ink (top), with subtle paper-tinted vignette
  const gradT = smoothstep(0, 1, uv().y);
  backdrop.material.colorNode = mix(surfNode, inkNode, gradT);
  group.add(backdrop);

  // ---- Featured card image plane ----
  const aspect = 512 / 320; // 1.6:1
  const cardW = 5.0;
  const cardH = cardW / aspect;
  const cardOpacity = uniform(0);
  const cardMat = new MeshBasicNodeMaterial({
    toneMapped: false,
    transparent: true
  });
  cardMat.opacityNode = cardOpacity;
  const cardMesh = new Mesh(new PlaneGeometry(cardW, cardH), cardMat);
  cardMesh.position.set(0, 0.2, 0);
  group.add(cardMesh);

  // Load card texture (async, cached)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    });
  }

  // ---- Accent divider line (signal red, <=10% of frame) ----
  const lineOpacity = uniform(0);
  const lineMat = new MeshBasicNodeMaterial({ toneMapped: false });
  lineMat.opacityNode = lineOpacity;
  lineMat.colorNode = accentNode;
  const line = new Mesh(new PlaneGeometry(1.6, 0.014), lineMat);
  line.position.set(0, -(cardH / 2) - 0.22, 0.01);
  group.add(line);

  // ---- Text overlay (rendered via fontAtlas) ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textObjects = [];

  for (const item of items) {
    const textStr = typeof item === 'string' ? item : item.text;
    if (!textStr) continue;
    const fontSize = item.typography?.fontSize ?? 31;
    const textObj = ctx.fontAtlas.createText(textStr, {
      fontSize,
      color: '#' + paper.getHexString(),
      align: 'center',
      maxWidthPx: 540
    });
    textObj.position.set(0, -(cardH / 2) - 0.55, 0.02);
    group.add(textObj);
    textObjects.push(textObj);
  }

  // ---- Entrance animation (weighted-settle, no linear easing) ----
  const tl = gsap.timeline();

  // Card rises in with overshoot settle
  tl.from(cardMesh.position, {
    y: 0.55,
    duration: 0.7,
    ease: 'power3.out'
  }, 0);

  tl.from(cardMesh.scale, {
    x: 0.95,
    y: 0.95,
    duration: 0.9,
    ease: 'power4.out'
  }, 0);

  tl.to(cardOpacity, {
    value: 1,
    duration: 0.5,
    ease: 'power2.out'
  }, 0);

  // Accent line draws in
  tl.from(line.scale, {
    x: 0,
    duration: 0.6,
    ease: 'power3.out'
  }, 0.25);

  tl.to(lineOpacity, {
    value: 0.9,
    duration: 0.4,
    ease: 'power2.out'
  }, 0.25);

  // Text fades up
  for (const tObj of textObjects) {
    tl.from(tObj.position, {
      y: '+=0.2',
      duration: 0.5,
      ease: 'power2.out'
    }, 0.3);
  }

  // ---- Event handlers ----
  group.userData.handlers = {};

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    tl.kill();
    backdrop.geometry.dispose();
    backdrop.material.dispose();
    cardMesh.geometry.dispose();
    if (cardMat.map) cardMat.map.dispose();
    cardMat.dispose();
    line.geometry.dispose();
    lineMat.dispose();
  };

  return group;
}
